defmodule Orchestra.Rollout.Trace do
  @moduledoc """
  A process-safe, ordered trace of everything that happens during a rollout
  execution. Usable from any process, including ones spawned by `Reactor` for
  asynchronous steps.
  """
  use GenServer

  @doc false
  def start_link(_opts) do
    GenServer.start_link(__MODULE__, [], name: __MODULE__)
  end

  @doc "Clears the trace."
  @spec reset() :: :ok
  def reset do
    GenServer.call(__MODULE__, :reset)
  end

  @doc "Records a `{event, label}` entry onto the end of the trace."
  @spec record({atom(), String.t()}) :: :ok
  def record({_event, _label} = entry) do
    GenServer.call(__MODULE__, {:record, entry})
  end

  @doc "Returns all recorded entries, in the order they were recorded."
  @spec entries() :: [{atom(), String.t()}]
  def entries do
    GenServer.call(__MODULE__, :entries)
  end

  @impl true
  def init(_), do: {:ok, []}

  @impl true
  def handle_call(:reset, _from, _state), do: {:reply, :ok, []}

  def handle_call({:record, entry}, _from, state), do: {:reply, :ok, [entry | state]}

  def handle_call(:entries, _from, state), do: {:reply, Enum.reverse(state), state}
end

defmodule Orchestra.Rollout.Semaphore do
  @moduledoc """
  A tiny counting semaphore used to bound the number of concurrent node
  deployments in flight at any one time.
  """
  use GenServer

  @limit 2

  @doc false
  def start_link(_opts) do
    GenServer.start_link(__MODULE__, %{available: @limit, waiting: :queue.new()}, name: __MODULE__)
  end

  @doc "Blocks until a permit is available, then acquires it."
  @spec acquire() :: :ok
  def acquire, do: GenServer.call(__MODULE__, :acquire, :infinity)

  @doc "Releases a previously acquired permit."
  @spec release() :: :ok
  def release, do: GenServer.cast(__MODULE__, :release)

  @impl true
  def init(state), do: {:ok, state}

  @impl true
  def handle_call(:acquire, _from, %{available: available} = state) when available > 0 do
    {:reply, :ok, %{state | available: available - 1}}
  end

  def handle_call(:acquire, from, %{waiting: waiting} = state) do
    {:noreply, %{state | waiting: :queue.in(from, waiting)}}
  end

  @impl true
  def handle_cast(:release, %{waiting: waiting} = state) do
    case :queue.out(waiting) do
      {{:value, from}, rest} ->
        GenServer.reply(from, :ok)
        {:noreply, %{state | waiting: rest}}

      {:empty, _} ->
        {:noreply, %{state | available: state.available + 1}}
    end
  end
